Import ListNotations.
Open Scope Z_scope.

Notation UNREG_W :=
  [(XS1_LO, XS1_HI); (XS2_LO, XS2_HI); (XS3_LO, XS3_HI); (0x64c402%Z, 0x64c404%Z); (0x64c400%Z, 0x64c402%Z)] (only parsing).

Definition unreg_loop_post (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (ra' s0' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem) (o1' o2' o3' o4' : byte),
    ms' = MS (mkR ra' sp gp tp t0' t1' t2' s0' (Z_to_bv 64 0x1ab8a8) a0' a1' a2' a3' a4' a5' a6' a7'
                  (Z_to_bv 64 2) (Z_to_bv 64 0x1d636) (Z_to_bv 64 0x1166c0) (Z_to_bv 64 (2^61)) (Z_to_bv 64 0x1175f0)
                  (Z_to_bv 64 0x10ca40) (Z_to_bv 64 0x117630) (Z_to_bv 64 0x117578) (Z_to_bv 64 0x119d78) (Z_to_bv 64 0)
                  t3' t4' t5' t6')
             F (Z_to_bv 64 0x54894) fc None m' (seg_rom asegs)
    /\ munch UNREG_W m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' XS1_LO XS1_HI /\ stk asegs m' XS2_LO XS2_HI /\ stk asegs m' XS3_LO XS3_HI
    /\ rw_cells asegs m' 0x64c402 [C1 o1'] /\ rw_cells asegs m' 0x64c400 [C1 o2'] /\ rw_cells asegs m' 0x64c401 [C1 o3'] /\ rw_cells asegs m' 0x64c403 [C1 o4'].

Lemma unreg_loop : forall (gs : list gdesc) (K : Z)
    (ra gp tp t0 t1 t2 s0 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (sp : word) F fc (m : mem) (o1 o2 o3 o4 : byte),
  Forall (fun g => gd_okb g = true) gs -> Z.of_nat (length gs) = K -> 1 <= K <= 453 ->
  gds_at m (0x1166c0 - 64 * K) gs ->
  rw_cells asegs m 0x11aa58 [C1 (Z_to_bv 8 1)] ->
  ro_cells asegs m 0x1195dc [C1 (Z_to_bv 8 1)] ->
  ro_cells asegs m 0x117590 [C4 (Z_to_bv 64 1)] ->
  ro_cells asegs m 0x119d78 [C8 (Z_to_bv 64 0x7fff8000)] ->
  ro_cells asegs m 0x1ab920 [C8 (Z_to_bv 64 0xffffffffffffffff)] ->
  ro_cells asegs m 0x10ca40 [C8 (Z_to_bv 64 0x1012a0)] ->
  stk asegs m XS1_LO XS1_HI -> stk asegs m XS2_LO XS2_HI -> stk asegs m XS3_LO XS3_HI ->
  rw_cells asegs m 0x64c402 [C1 o1] -> rw_cells asegs m 0x64c400 [C1 o2] -> rw_cells asegs m 0x64c401 [C1 o3] -> rw_cells asegs m 0x64c403 [C1 o4] ->
  mem_inv asegs m ->
  evt asegs (unreg_loop_post sp gp tp F fc m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 0x1ab8a8) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 2) (Z_to_bv 64 0x1d636) (Z_to_bv 64 (0x1166c0 - 64 * K)) (Z_to_bv 64 (2^61)) (Z_to_bv 64 0x1175f0)
             (Z_to_bv 64 0x10ca40) (Z_to_bv 64 0x117630) (Z_to_bv 64 0x117578) (Z_to_bv 64 0x119d78) (Z_to_bv 64 K)
             t3 t4 t5 t6)
        F (Z_to_bv 64 0x54690) fc None m (seg_rom asegs)).
Proof.
